vector<uint32_t> UINT32(int i){
     uint32_t AL;
     uint32_t BE;
     AL=Alpha_1[i][0]+Alpha_1[i][1]*2+Alpha_1[i][2]*4+Alpha_1[i][3]*8+Alpha_1[i][4]*16;
     BE=Beta_0[i][0]+Beta_0[i][1]*2+Beta_0[i][2]*4+Beta_0[i][3]*8+Beta_0[i][4]*16;
     return {AL, BE};    
}

MatrixType2D DDT4(vector<vector<int>> c){
    MatrixType2D L(5, vector<int>(6, 0));
    for(int i = 0; i < 5; i++){
        L[i][i]=1;    
    }
    for(int i = 0; i < 5; i++){
        if(c[i][(i+1)%5]+c[i][(i+2)%5]==1){
            L[(i+1)%5][(i+1)%5]=1^c[i][(i+1)%5];
            L[(i+2)%5][(i+2)%5]=1^c[i][(i+2)%5];
            
            if(c[i][(i+1)%5]==1){
                L[(i+1)%5][5]=L[(i+1)%5][5]^c[i][5];
                if(c[i][5]==1){
                    L[(i+4)%5][i]= 1;
                    L[(i+4)%5][5]=L[(i+4)%5][5]^1;
                }
                else{
                    L[i][(i+2)%5]=1;
                }
            }
            else{
                L[(i+2)%5][5]=L[(i+2)%5][5]^c[i][5];
                if(c[i][5]==1){
                    L[i][(i+1)%5]=1;
                    L[i][5]=L[i][5]^1;    
                }
                else{
                    L[(i+1)%5][(i+3)%5]=1;
                }
            }
        }
    }
    for(int i = 0; i < 5; i ++){
        if(c[i][(i+1)%5]+c[i][(i+2)%5]==2){
            for(int j = 0; j < 5; j++){
                if(L[j][(i+1)%5] == 1 && L[j][(i+2)%5] == 1){
                    L[j][(i+1)%5] = 0;
                    L[j][(i+2)%5] = 0;	
                    if(c[i][5]==1)
                        L[j][5]= L[j][5]^1;
                }
            }
        }
        if(c[i][5]==1){
            L[i][5]=L[i][5]^1;
        }
    }
    return L;
} 

MatrixType2D CC(uint32_t m, uint32_t n) { 
    MatrixType2D c(5, vector<int>(6, 0)); 
    int x[5];
    int y[5];
    for(int i = 0; i < 5; i++) {
        x[i] = (m >> i) & 1;
        y[i] = (n >> i) & 1;
    }
    for (int i = 0; i < 5; i++) {
        int c2_i = x[i] ^ ((x[(i + 1) % 5] ^ 1) * x[(i + 2) % 5]);
        c[i][5] = y[i] ^ c2_i;
    }
    c[0][1] = x[2]; c[0][2] = x[1];
    c[1][2] = x[3]; c[1][3] = x[2];
    c[2][3] = x[4]; c[2][4] = x[3];
    c[3][0] = x[4]; c[3][4] = x[0];
    c[4][0] = x[1]; c[4][1] = x[0];
    return c;
}

MatrixType2D DDT2or4(uint32_t m, uint32_t n) {
    MatrixType2D c = CC(m, n);
    return DDT4(c);
}

// 傳值 (MatrixType2D D) 來運算，不直接影響外面的狀態，但用來判斷是否合理
bool Gaussian(MatrixType2D D){
    int rows = D.size();
    int cols = D[0].size();
    int pivot_row = 0;
    
    for (int c = 0; c < cols - 1 && pivot_row < rows; c++) {
        int sel = pivot_row;
        while (sel < rows && D[sel][c] == 0) sel++;
        if (sel == rows) continue;
        
        if (sel != pivot_row) {
            swap(D[pivot_row], D[sel]);
        }

        for (int i = 0; i < rows; i++) {
            if (i != pivot_row && D[i][c] == 1) {
                for (int k = c; k < cols; k++) {
                    D[i][k] ^= D[pivot_row][k]; 
                }
            }
        }
        pivot_row++;
    }
    
    // 如果出現 0 = 1 的情況，代表矛盾 (false)
    for (int i = pivot_row; i < rows; i++) {
        if (D[i][cols - 1] == 1) {
            return false; 
        }
    }
    return true; 
}


MatrixType2D PlusEq(MatrixType2D c, vector<int> q){
    MatrixType2D L(5, vector<int>(6, 0)); 
    
    for(int j = 0; j < 5; j++){ 
       L[j][j]=1;     
    }

    for(int i = 0; i < 5; i++){
        int sum_c = c[i][(i+1)%5] + c[i][(i+2)%5];

        if(sum_c == 1){
            L[(i+1)%5][(i+1)%5] = 1 ^ c[i][(i+1)%5];
            L[(i+2)%5][(i+2)%5] = 1 ^ c[i][(i+2)%5];
            
            if(c[i][(i+1)%5] == 1){
                L[(i+1)%5][5] = L[(i+1)%5][5]^c[i][5];
                if(c[i][5] == 1){
                    L[(i+4)%5][i] = 1;
                    L[(i+4)%5][5] = L[(i+4)%5][5] ^ 1;
                } else {
                    L[i][(i+2)%5] = 1;
                }
            } else {
                L[(i+2)%5][5] =L[(i+2)%5][5]^ c[i][5];
                if(c[i][5] == 1){
                    L[i][(i+1)%5] = 1;
                    L[i][5] = (L[i][5] + 1) % 2;  
                } else {
                    L[(i+1)%5][(i+3)%5] = 1;
                }
            }
        } 
        else if(sum_c == 2) {
            if(c[i][5] == 1){
                L[i][5] = L[i][5] ^ 1;
            }
        }
    }
    
    int Q = 0;
    for(int i = 0; i < 5; i++) Q = Q+q[i];
    
    for(int j = 0; j < 5; j++){
        if(c[j][(j+1)%5] + c[j][(j+2)%5] == 0 && 
           c[(j+4)%5][(j+1)%5] == 0 && 
           c[(j+1)%5][(j+2)%5] == 0){
            if(Q==1){
                if(q[(j+1)%5]==1 && q[5]==0) L[j][(j+2)%5]=1;
                if(q[(j+2)%5]==1 && q[5]==1) {
                    L[j][(j+1)%5]=1;
                    L[j][5]= 1 ;
                }
            }
            if(Q == 2&&q[5]==1)L[j][5]=1;
        }
    }
    return L;
}

// 【重點改動】：E_M 改為傳參考 (MatrixType2D&)，允許內部修改它
MatrixType2D DDT8(uint32_t m, uint32_t n, vector<bool>& is_nonlinear, int sbox_index) {
    MatrixType2D c = CC(m, n); 
    MatrixType2D L(5, vector<int>(6, 0)); 
    
    for(int j = 0; j < 5; j++){ 
        L[j][j]=1;   
        // 抓出無法線性化的那個 bit
        if(c[j][(j+1)%5] + c[j][(j+2)%5] == 0 && 
           c[(j+4)%5][(j+1)%5] == 0 && 
           c[(j+1)%5][(j+2)%5] == 0) {
            
            // 標記在全域的 1600 bit 陣列中
            is_nonlinear[sbox_index * 5 + j] = true; 
            L[j][j] = 0; // 局部矩陣清零，因為我們不會用到它
        }
    }

    for(int i = 0; i < 5; i++){
        int sum_c = c[i][(i+1)%5] + c[i][(i+2)%5];
        if(sum_c == 1){
            L[(i+1)%5][(i+1)%5] = 1 ^ c[i][(i+1)%5];
            L[(i+2)%5][(i+2)%5] = 1 ^ c[i][(i+2)%5];
            
            if(c[i][(i+1)%5] == 1){
                L[(i+1)%5][5] = L[(i+1)%5][5]^c[i][5];
                if(c[i][5] == 1){
                    L[(i+4)%5][i] = 1;
                    L[(i+4)%5][5] = L[(i+4)%5][5] ^ 1;
                } else {
                    L[i][(i+2)%5] = 1;
                }
            } else {
                L[(i+2)%5][5] =L[(i+2)%5][5]^ c[i][5];
                if(c[i][5] == 1){
                    L[i][(i+1)%5] = 1;
                    L[i][5] = (L[i][5] + 1) % 2;  
                } else {
                    L[(i+1)%5][(i+3)%5] = 1;
                }
            }
        } 
        else if(sum_c == 2) {
            if(c[i][5] == 1){
                L[i][5] = L[i][5] ^ 1;
            }
        }
    }
    return L;
}

MatrixType2D Substitution(const MatrixType2D& M, const MatrixType2D& N, const vector<bool>& is_nonlinear) {
    MatrixType2D m(M.size(), vector<int>(M[0].size(), 0));
    
    for (int i = 0; i < M.size(); i++) {
        bool equation_is_poisoned = false;
        
        // 檢查這條方程式有沒有踩到非線性的雷
        for (int j = 0; j < 1600; j++) {
            if (M[i][j] == 1 && is_nonlinear[j] == true) {
                equation_is_poisoned = true;
                break; 
            }
        }
        
        // 如果踩到雷，這條方程式現在不能用，直接跳過（留在 m 裡就是整列 0，不影響高斯消去）
        if (equation_is_poisoned) {
            continue;
        }

        // 如果是乾淨的純線性方程式，就乖乖代入
        for (int j = 0; j < 1600; j++) { 
            if (M[i][j] == 1) {
                for (int k = 0; k < 1601; k++) {
                    m[i][k] ^= N[j][k];
                }
            }
        }
        // 常數項處理
        m[i][1600] ^= M[i][1600]; 
    }
    return m;
}

MatrixType2D Merge(MatrixType2D M, MatrixType2D N){
	MatrixType2D m(M.size() + N.size(), vector<int>(M[0].size()));
	for(int i = 0; i < M.size(); i++)m[i] = M[i];
	for(int i = M.size(); i < M.size() + N.size(); i++) m[i] = N [i - M.size()];
	return m;	
}


